import{_ as t,o as a,c as i,ai as n}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"[决策] 为何暂不用 TDengine","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/industrial-digitalization/decisions/04-no-tdengine.md","filePath":"tech-system/industrial-digitalization/decisions/04-no-tdengine.md"}'),d={name:"tech-system/industrial-digitalization/decisions/04-no-tdengine.md"};function r(l,e,o,s,h,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="决策-为何暂不用-tdengine" tabindex="-1"><code>[决策]</code> 为何暂不用 TDengine <a class="header-anchor" href="#决策-为何暂不用-tdengine" aria-label="Permalink to “[决策] 为何暂不用 TDengine”">​</a></h1><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>状态</td><td>🔵 设计中</td></tr><tr><td>类型</td><td><code>[决策]</code> Rejected（当前阶段）</td></tr><tr><td>项目</td><td>Mini MES V0</td></tr><tr><td>证据</td><td>待写入量/查询延迟实测</td></tr></tbody></table><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>底稿与常见方案常把 TDengine/Influx 标成工业时序标配。</p><h2 id="判断" tabindex="-1">判断 <a class="header-anchor" href="#判断" aria-label="Permalink to “判断”">​</a></h2><p>TDengine <strong>能用，但 V0 不必用。</strong></p><p>V0 规模预期：实验室级模拟设备（如几十～一百台）、秒级采样、单机可观察。MySQL 存采样表足够支撑「简单曲线 + 短周期历史」。引入 TSDB 的收益（压缩、按设备超级表、长期聚合）在<strong>没有数字</strong>前无法证明。</p><h2 id="暂不用的原因" tabindex="-1">暂不用的原因 <a class="header-anchor" href="#暂不用的原因" aria-label="Permalink to “暂不用的原因”">​</a></h2><ol><li>运维与心智成本 &gt; 当前数据量收益</li><li>多一个存储 = 多一套备份、监控、不一致问题</li><li>想先确认点表模型与写入路径，再决定是否迁移历史</li></ol><h2 id="重新评估触发条件-示例" tabindex="-1">重新评估触发条件（示例） <a class="header-anchor" href="#重新评估触发条件-示例" aria-label="Permalink to “重新评估触发条件（示例）”">​</a></h2><ul><li>日写入行数明显超出单机 MySQL 舒适区（用 Lab 数字填）</li><li>曲线/聚合查询延迟不可接受</li><li>需要按设备长期降采样与保留策略</li></ul><p>触发后做专项 Lab（可标 ❌ 暂停也算结果），再改本页状态。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><p><strong>第一阶段继续 MySQL 历史表；TDengine 是选项不是起点。</strong></p>',15)])])}const p=t(d,[["render",r]]);export{_ as __pageData,p as default};
